import re
from lxml import etree as ET
from future.utils import python_2_unicode_compatible


@python_2_unicode_compatible
class PMSetup(object):
    """
    PMSetup represents the tree of managed object with attached pm counter value.

    A PMSetup offers methods to access pi values.

    It is based on a slightly modified XML format, which is derived from the PM counter file,
    which can be displayed like this:

        print(pm_setup)


    Methods:

    - **`findall`**: Find all values for a performance indicator.

    - **`keys`**: Return performance indicator names, which are present in this PMSetup.

    - **`paths`**: Return performance indicator paths, which are present in this PMSetup.

    - **`xpath`**: Return a list of parameter values, which match an XPath expression, that specifies parameter nodes.

    - **`pi_dict`**: Return PI name and value in dictionary format.


    Attributes:

    - **`pm_xml`**: PMSetup in XML format

    - **`regex`**: Optional regular expression to specify a subset of parameter names

    - **`path`**: XPath expression

    - **`pi_name`**: Performance indicator name

    """

    def __init__(self, pm_xml, **kwargs):
        """
        Create a PMSetup from an XML string.

        :param str pm_xml:
            This XML element is a slightly converted PMSetup to simplify XPath expressions:
            Multiple PMSetup entries unified and converted to below format

            .. code-block:: xml

              <PMSetup>
                <PLMN id="PLMN">
                    <MRBTS id="1900">
                        <NRBTS id="1">
                            <NX2CB M55110C00001="3" M55110C00002="2" M55110C00003="1" M55110C00004="1"/>
                            <NRCELL id="1">
                                <NE1CC M55122C00001="0" M55122C00002="0"/>
                                <NRRCC M55124C00001="0" M55124C00501="0" M55124C00502="0" M55124C00503="0"/>
                            </NRCELL>
                        </NRBTS>
                    </MRBTS>
                </PLMN>
              </PMSetup>
        """

        super(PMSetup, self).__init__(**kwargs)
        self.__pm_xml = pm_xml

    def __str__(self):
        """
        Return string representation of the PMSetup.

        :return: string representation of the PMSetup
        :rtype: str
        """

        return ET.tostring(self.__pm_xml, pretty_print=True).strip().decode()

    @property
    def pm_xml(self):
        """
        Return the XML representation of this PMSetup.

        :return: XML representation of this PMSetup
        :rtype: lxml.etree._Element
        """

        return self.__pm_xml

    def xpath(self, path):
        """
        Return parameter values, which match an XPath expression, that specifies parameter nodes.

        xpath example:

        .. code-block:: python

            pm_setup.xpath(".//@M55118C01000")

        Output:

        .. code-block:: python

            ['19885971']

        :param str path: XPath expression

        :return: list of parameter values
        :rtype: list

        """

        return self.__pm_xml.xpath(path)

    def findall(self, pi_name):
        """
        Find all values for a PI name.

        Example:

        .. code-block:: python

            pm_setup.findall('M55110C00001')

        Output:

         .. code-block:: python

            ['1']

        :param str pi_name: PI name in a managed object
        :return: list of PI values
        :rtype: list(str)
        """
        pi_values = []
        pi_values.extend(self.xpath(
            ".//@{pi_name}".format(pi_name=pi_name)))
        return pi_values

    def paths(self, regex=None):
        """
        Return performance indicator (PI) name paths (optionally matching a regular expression),
        which are present in this PmSetup.

        Example:

        .. code-block:: python

            pm_setup.paths("M55314C00002")

        Output:

        .. code-block:: python

            ["PLMN[@id='PLMN']/MRBTS[@id='1900']/NRBTS[@id='1']/NRDU[@id='1']/NF1UD/@M55314C00002"]

        :param str regex: optional regular expression to specify a subset of parameter name paths
        :return: list of parameter name paths
        :rtype: list(str)
        """

        paths = [
            "/".join(
                [
                    "%s[@id='%s']" % (parent_elem.tag, parent_elem.get("id"))
                    if "id" in parent_elem.keys() else parent_elem.tag
                    for parent_elem in element.xpath("./ancestor-or-self::*")[1:]]) + "/@%s" % attr
            for element in self.pm_xml.findall(".//*")
            for attr in element.keys() if attr != "id"]
        if regex is None:
            return paths
        else:
            return [path for path in paths if re.search(regex, path)]

    def keys(self, regex=None):
        """
        Return pi names (optionally matching a regular expression), which are present in this PMSetup.

        Example:

        .. code-block:: python

            >> pmsetup.keys('M55110C0000*')

        Output:

        .. code-block:: python

            ['M55110C00001', 'M55110C00002', 'M55110C00003', 'M55110C00004'
            ...
            ...
            ...
            'M55110C00029', 'M55110C00030', 'M55110C00031', 'M55110C00032']

        :param str regex: optional regular expression to specify a subset of parameter names.
        :return: list of keys
        :rtype: list(str)
        """
        pi_names = sorted({key
                           for element in self.__pm_xml.findall(".//*")
                           for key in element.keys()
                           if key != "id"})
        if regex is None:
            return pi_names
        else:
            return [
                pi_name
                for pi_name in pi_names
                if re.search(regex, pi_name)]

    def __getitem__(self, pi_name):
        """
        Return a PI value for a PI name.

        Example:

        .. code-block:: python

            pm_setup['M55800C00001']

        Output:

        .. code-block:: python

            "1"

        :param str pi_name: PI name
        :return: PI value
        :rtype: :class:`lxml.etree._ElementStringResult`
        :raises:
            KeyError, if no PI name in the current PMSetup matches regex
            LookupError, if more than one PI name matches regex

        """

        result_list = self.findall(pi_name)
        # print result_list
        length = len(result_list)
        if length == 0:
            raise KeyError(pi_name)
        elif length > 1:
            raise LookupError(pi_name)
        else:
            return result_list[0]

    def __contains__(self, pi_name):
        """
        Check whether there is any PI name in this PMSetup.

        Example:

        .. code-block:: python

            if "M55118C01000" in pmsetup:
                # If key found then do some operation

        :param str pi_name: PI name, that will be checked for presence
        :return: True, if at least one PI name in the current PMSetup matches.
        :rtype: bool
        """
        return bool(self.findall(pi_name))

    def pi_dict(self, *args):
        """
        Return performance indicator values in a dictionary format.

        output format: {pi_name1: {pi_path: pi_value}, pi_name2: {pi_path: pi_value}}

        Example:

        .. code-block:: python

            pm_setup.pi_dict("M55118C01000", "M55800C00001")

        Output:

        .. code-block:: python

            {
                'M55118C01000': {
                    'MRBTS-1900/NRBTS-1/NRCELL-1': '19885971'},
                'M55800C00001': {
                    'MRBTS-1900/MNL-1/MNLENT-1': '0',
                    'MRBTS-1900/MNL-1/MNLENT-2': '0'}}

        :param Iterable[str] args: PI names
        :return: dict of dictionaries containing pi_name: {pi_path: pi_value}
        :rtype: dict(dict)
        """
        return {
            pi: dict(
                zip(
                    [
                        "/".join(
                            [
                                "%s-%s" % (parent_elem.tag, parent_elem.get("id"))
                                for parent_elem in pi_elem.xpath("./ancestor::*")[2:]])
                        for pi_elem in self.__pm_xml.xpath("//*[@%s]" % pi)],
                    self.__pm_xml.xpath("//@%s" % pi)))
            for pi in args
        }
